SELECT DATE_TRUNC('QUARTER', hire_date) AS quarter_start, job_title, SUM(salary) AS total_salary, COUNT_IF(job_title = 'Engineer') AS engineer_events, MAX(salary) AS max_salary, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN level = 'L3' THEN 1 END), 0), 2) AS salary_per_l3, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', hire_date) ORDER BY ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN level = 'L3' THEN 1 END), 0), 2) DESC) AS salary_per_l3_rank FROM employees GROUP BY DATE_TRUNC('QUARTER', hire_date), job_title
